#!/bin/bash
# usage: gen.sh <n> <name> <screenshot> <extra>
cd /home/agent/rice-farmer/app/design-vc6
L=$(sed -n "${1}p" jobs.txt); n=${L%%|*}; R=${L#*|}; name=${R%%|*}; R=${R#*|}; shot=${R%%|*}; extra=${R#*|}
mkdir -p w/$n && cd w/$n
BASE="You are a senior mobile UI designer. The first attached image is the CURRENT screenshot of the '$name' screen of a Thai rice-farmer app (RiceOS). Redesign it as ONE high-fidelity mobile UI mockup, portrait 390x844 ratio, a single phone screen filling the whole image (no device frame, no extra canvas). KEEP the same Thai labels, content and structure as the screenshot (copy the real Thai text exactly; do not invent KPI numbers, prices, statistics, or agency logos or government seals). Style: clean government-grade but warm, elderly-friendly: body text at least 16px, big tap targets (>=48px), high contrast, white cards with rounded corners and soft shadow, dark-green top bar, ONE consistent outline icon set, IBM Plex Sans Thai typography, fixed bottom navigation. Palette: Primary Forest Green #0B5A2A, RiceOS Green #1D7A3E, Harvest Gold #D4A017, Warm White #F7F8F5, Alert Yellow #E9B949, Risk Red #C93C32 (status always with text or icon). The second attached image is only a STYLE reference (a poster by the client): borrow its warm Thai agritech feel, not its content. No neon glow, no clutter, no tiny text. Screen specifics: $extra Use your image generation tool (not code drawing). Save the PNG into the current directory as screen$n.png and print its path."
/home/agent/.local/bin/codex exec --skip-git-repo-check -s workspace-write -m gpt-6.1-sol -i /home/agent/rice-farmer/app/tests/shots/vc6/$shot -i /home/agent/rice-farmer/docs/from-nopadon-20261112/20261113-1758/8507.jpg -- "$BASE" > log.txt 2>&1
echo done $n >> ../../done.txt
